<template>
  <div class="profile">

    <table class="" v-if="user">

      <template v-if="user">

        <!-- Employee properties -->
        <tr>
          <th class="first_row" colspan="2">個人情報 / Personal information</th>
        </tr>

        <tr
          v-for="(val, key) in user.properties"
          v-bind:key="key">
          <td v-if="key !== 'password_hashed'">{{key}}</td>
          <td v-if="key !== 'password_hashed'">{{val}}</td>
        </tr>

      </template>

      <template v-if="groups.length > 0">

        <!-- Groups -->
        <tr>
          <th class="" colspan="2">Groups</th>
        </tr>

        <tr
          v-for="(group, index) in groups"
          v-bind:key="`group_${index}`">
          <td>{{group.labels[0]}}</td>
          <td>{{group.properties.name}}</td>

        </tr>
      </template>

      <template v-if="workplaces.length > 0">

        <!-- Workplaces-->
        <tr>
          <th class="" colspan="1000">Workplaces</th>
        </tr>

        <tr
          v-for="workplace in workplaces"
          v-bind:key="workplace.identity.low">
          <td>{{workplace.labels[0]}}</td>
          <td>{{workplace.properties.name}}</td>

          <td>
            <button type="button" v-on:click="leave_workplace(workplace.identity.low)">Leave</button>
          </td>

        </tr>



        <!-- Option to add a workplace -->
        <tr v-if="all_workplaces.length > 0">
          <td>Add workplace</td>
          <td>
            <select ref="new_workplace_select" >
              <option
                v-for="workplace in all_workplaces"
                v-bind:key="workplace.identity.low"
                v-bind:value="workplace.identity.low">{{workplace.properties.name}}</option>
            </select>
          </td>
          <td>
            <button type="button" v-on:click="join_workplace()">Join</button>
          </td>
        </tr>
      </template>

    </table>

  </div>
</template>

<script>
// @ is an alias to /src

export default {
  name: 'MyProfile',
  components: {

  },
  data(){
    return {
      user: null,
      groups: [],
      workplaces: [],

      all_workplaces: [],
    }
  },
  mounted(){
    this.get_employee_information()
    // Get all workplaces for <select> to join a new workplace
    this.get_all_workplaces()
  },
  methods: {

    get_employee_information(){
      this.axios.post(`${process.env.VUE_APP_EMPLOYEE_MANAGER_URL}/get_employee`, {
        employee_number: this.$route.query.employee_number
      })
      .then(response => {
        this.user = response.data
        this.get_groups()
        this.get_workplaces()
      })
      .catch(error => alert(error))
    },

    get_groups(){
      this.axios.post(`${process.env.VUE_APP_EMPLOYEE_MANAGER_URL}/get_groups_of_employee`, {
        employee_number: this.$route.query.employee_number
      })
      .then(response => {
        this.groups.splice(0,this.groups.length)
        response.data.forEach((record) => {
          let group = record._fields[record._fieldLookup['group']]
          this.groups.push(group)
        });

      })
      .catch(error => alert(error))
    },
    get_workplaces(){
      this.axios.post(`${process.env.VUE_APP_EMPLOYEE_MANAGER_URL}/get_workplaces_of_employee`, {
        employee_number: this.$route.query.employee_number
      })
      .then(response => {
        this.workplaces.splice(0,this.workplaces.length)
        response.data.forEach((record) => {
          let workplace = record._fields[record._fieldLookup['workplace']]
          this.workplaces.push(workplace)
        });

      })
      .catch(error => alert(error))
    },

    join_workplace(){
      this.axios.post(`${process.env.VUE_APP_EMPLOYEE_MANAGER_URL}/join_workplace`, {
        employee_number: this.$route.query.employee_number,
        workplace_id: this.$refs.new_workplace_select.value
      })
      .then(response => {
        this.workplaces.splice(0,this.workplaces.length)
        response.data.forEach((record) => {
          let workplace = record._fields[record._fieldLookup['workplace']]
          this.workplaces.push(workplace)
        });
        this.get_workplaces()

      })
      .catch(error => alert(error))


    },

    leave_workplace(workplace_id){
      if(confirm('ホンマに？')){
        this.axios.post(`${process.env.VUE_APP_EMPLOYEE_MANAGER_URL}/leave_workplace`, {
          employee_number: this.$route.query.employee_number,
          workplace_id: workplace_id
        })
        .then( () => { this.get_workplaces() })
        .catch(error => alert(error))
      }



    },

    get_all_workplaces(){
      this.axios.get(`${process.env.VUE_APP_EMPLOYEE_MANAGER_URL}/all_workplaces`)
      .then(response => {
        this.all_workplaces.splice(0,this.all_workplaces.length)
        response.data.forEach((record) => {
          let workplace = record._fields[record._fieldLookup['workplace']]
          this.all_workplaces.push(workplace)

        });
      })
      .catch(error =>console.log(error));
    },

  }
}
</script>

<style scoped>

table {
  width: 100%;
  border-collapse: collapse;
}

tr:not(:last-child) {
  border-bottom: 1px solid #dddddd;
}

td, th {
  padding: 2px;
}

th:not(.first_row) {
  padding-top: 25px;
}

</style>
